export const DEFAULT_LEFT = 400
export const MIN_LEFT = 280
export const MIN_RIGHT = 360
/** Divider + column gaps; matches the CSS min() in SplitLayout's grid template. */
export const GAPS = 16

export interface Bounds {
  min: number
  max: number
}

export const splitBounds = (total: number): Bounds => ({ min: MIN_LEFT, max: Math.max(MIN_LEFT, Math.round(total - MIN_RIGHT - GAPS)) })

export const clampWidth = (w: number, b: Bounds) => Math.round(Math.max(b.min, Math.min(w, b.max)))

/** New width for a key on the focused divider, or undefined when the key is not handled. */
export function widthForKey(key: string, shift: boolean, current: number, b: Bounds): number | undefined {
  const step = shift ? 80 : 20
  switch (key) {
    case 'ArrowLeft':
      return clampWidth(current - step, b)
    case 'ArrowRight':
      return clampWidth(current + step, b)
    case 'Home':
      return b.min
    case 'End':
      return b.max
    default:
      return undefined
  }
}

const pct = (w: number, total: number) => Math.round((w / total) * 100)

/** aria-valuenow/min/max as percentages of the layout width, plus a readable aria-valuetext. */
export function splitValue(width: number, total: number) {
  const b = splitBounds(total)
  const now = pct(clampWidth(width, b), total)
  return { now, min: pct(b.min, total), max: pct(b.max, total), text: `Ľavý stĺpec ${now} % šírky (${Math.round(width)} px)` }
}
